// triggerBytes = bytes that must accumulate before a cycle fires
const triggerBytes = 100 * 1024 * 1024; // 100 MB of garbage per cycle
function interval(allocRateMBs) {
  const rate = allocRateMBs * 1024 * 1024; // bytes/s
  return triggerBytes / rate; // seconds between cycles
}
const a = interval(50);    // steady cache, 50 MB/s
const b = interval(1024);  // high-throughput API, 1 GB/s
console.log('cache cycles every', a.toFixed(1), 's');
console.log('api cycles every', b.toFixed(3), 's');
console.log('api is', Math.round(a / b), 'x more frequent');
